    "title": "Git LFS HTTPS Lock List API Response",
    "type": "object",
    "properties": {
        "locks": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "id": {
                        "type": "string"
                    },
                    "path": {
                        "type": "string"
                    },
                    "locked_at": {
                        "type": "string"
